int sctp_get_assoc_stats(struct sock *sk, int len, char __user *optval, int __user *optlen) {
    struct sctp_association *asoc;
    struct sctp_assoc_stats stats;
    int ret = 0;

    if (len < sizeof(stats.assoc_id)) {
        return -EINVAL;
    }

    asoc = sctp_id2assoc(sk, *(sctp_assoc_t __user *)optval);
    if (!asoc) {
        return -EINVAL;
    }

    memset(&stats, 0, sizeof(stats));
    stats.assoc_id = *(sctp_assoc_t __user *)optval;

    stats.cnt_sacks = asoc->stats.cnt_sacks;
    stats.cnt_outdata = asoc->stats.cnt_outdata;
    stats.cnt_retrans = asoc->stats.cnt_retrans;
    stats.cnt_fast_retrans = asoc->stats.cnt_fast_retrans;
    stats.cnt_challenge = asoc->stats.cnt_challenge;
    stats.cnt_cookie = asoc->stats.cnt_cookie;
    stats.cnt_timeout = asoc->stats.cnt_timeout;
    stats.cnt_pmtu = asoc->stats.cnt_pmtu;
    stats.cnt_sacks = asoc->stats.cnt_sacks;
    stats.cnt_reconfig = asoc->stats.cnt_reconfig;
    stats.cnt_sack_retrans = asoc->stats.cnt_sack_retrans;

    if (asoc->rto_max > asoc->rto) {
        stats.max_rto = asoc->rto_max;
    } else {
        stats.max_rto = asoc->rto;
    }

    if (copy_to_user(optval, &stats, sizeof(stats))) {
        return -EFAULT;
    }

    if (put_user(len, optlen)) {
        return -EFAULT;
    }

    return ret;
}

int sctp_get_assoc_stats(struct sock *sk, int len, char __user *optval, int __user *optlen)
{
    struct sctp_assoc_stats __user *u_stats;
    struct sctp_assoc_stats stats;
    struct sctp_association *asoc;
    int ret = 0;

    if (len < sizeof(stats.assoc_id)) {
        return -EINVAL;
    }

    u_stats = (struct sctp_assoc_stats __user *)optval;

    if (copy_from_user(&stats, u_stats, sizeof(stats.assoc_id))) {
        return -EFAULT;
    }

    asoc = sctp_id2assoc(sk, stats.assoc_id);
    if (!asoc) {
        return -EINVAL;
    }

    stats.max_rto = asoc->rto_max;
    stats.active_streams = asoc->c.sinit_num_streams;
    stats.established_time = jiffies_to_msecs(jiffies - asoc->time_created);
    stats.retransmits = asoc->retransmits;
    stats.retransmitted_pkts = asoc->retransmitted;
    stats.packets_sent = asoc->sent;
    stats.packets_received = asoc->received;
    stats.ack_received = asoc->acks_recvd;
    stats.ack_sent = asoc->acks_sent;

    if (copy_to_user(u_stats, &stats, sizeof(stats))) {
        return -EFAULT;
    }

    if (put_user(sizeof(stats), optlen)) {
        return -EFAULT;
    }

    return ret;
}

int sctp_get_assoc_stats(struct sock *sk, int len, char __user *optval, int __user *optlen)
{
    struct sctp_assoc_stats stats;
    struct sctp_association *asoc;
    int error = -EINVAL;

    if (len < sizeof(stats.assoc_id))
        return -EINVAL;

    if (copy_from_user(&stats, optval, sizeof(stats)))
        return -EFAULT;

    asoc = sctp_id2assoc(sk, stats.assoc_id);
    if (!asoc)
        return -ENOENT;

    stats.stats = sctp_get_stats(asoc);
    if (!stats.stats)
        return -ENOMEM;

    stats.max_rto = asoc->rto_max;
    stats.current_rto = asoc->rto;

    if (put_user(len, optlen))
        return -EFAULT;

    if (copy_to_user(optval, &stats, len))
        return -EFAULT;

    return 0;
}

int sctp_get_association_stats(struct sock *sk, int len, char __user *optval, int __user *optlen)
{
    struct sctp_association *asoc;
    struct sctp_assoc_stats stats;
    int ret = -EINVAL;

    if (len < sizeof(stats.assoc_id))
        return -EINVAL;

    if (copy_from_user(&stats.assoc_id, optval, sizeof(stats.assoc_id)))
        return -EFAULT;

    asoc = sctp_id2assoc(sk, stats.assoc_id);
    if (!asoc)
        return -ENOENT;

    stats.out_of_order = asoc->stats.out_of_order;
    stats.retransmits = asoc->stats.retransmits;
    stats.rto_max = asoc->rto_max;
    stats.data_snd = asoc->stats.data_snd;
    stats.data_rcv = asoc->stats.data_rcv;

    ret = 0;
    len = min_t(int, len, sizeof(stats));
    if (copy_to_user(optval, &stats, len))
        ret = -EFAULT;

    if (optlen && put_user(len, optlen))
        ret = -EFAULT;

    return ret;
}

int sctp_get_association_stats(struct sock *sk, int len, char __user *optval, int __user *optlen)
{
    struct sctp_association *asoc;
    struct sctp_stats stats;
    int ret;

    if (len < sizeof(stats.assoc_id))
        return -EINVAL;

    if (copy_from_user(&stats, optval, sizeof(stats)))
        return -EFAULT;

    asoc = sctp_id2assoc(sk, stats.assoc_id);
    if (!asoc)
        return -ENOENT;

    stats.cummits = asoc->stat.cummits;
    stats.retransmits = asoc->stat.retransmits;
    stats.rto_max = asoc->rto_max;
    stats.rto_current = asoc->rto;
    stats.active = asoc->active;

    if (asoc->stat.rto_max > asoc->rto_current)
        stats.rto_current = asoc->stat.rto_max;

    if (copy_to_user(optval, &stats, sizeof(stats)))
        return -EFAULT;

    if (put_user(sizeof(stats), optlen))
        return -EFAULT;

    return 0;
}
